<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, beijingTime, queryParams } from './api'
import { metricLabel, metricValue, resourceCharts, trendOption, healthCharts } from './charts'
import MetricChart from './MetricChart.vue'
import NodeDialog from './NodeDialog.vue'
import { servers, statusLabel, rangeQuery, requestKey, type Settings, errorMessage, type Server, type Trend } from './monitoring'
function deploymentLabel(value?:string){return ({complete:'已验收','go-switched':'已启动，待验收','go-prepared':'准备中','go-rolled-back':'已回退',uninstalled:'已卸载'} as Record<string,string>)[value || ''] || (value ? '部署处理中' : '尚无部署记录')}
function runtimeLabel(mode?:string) {return mode==='native'?'直接运行 Go':mode==='docker'?'Docker 容器':'尚未确认'}
const systemHealth = ref<{mode:string;database:string;pending_notifications:number;oldest_pending:number;pending_email:number;oldest_email:number;email_enabled:boolean;manager:{available:boolean;message?:string;watchdog_phase?:string}}>()
const systemError=ref(''), route=useRoute(),router=useRouter()
const items = ref<Server[]>([]), data = ref<Trend>({ points: [], resolution_seconds: 30, start: 0, end: 0 }), error = ref(''), q = ref(String(route.query.q||'')), status = ref(String(route.query.status||'')), hours = ref(1), tab = ref('resources'), device = ref(''), networkDevice = ref(''), customStart = ref(''), customEnd = ref(''), nodeDialog = ref(false), editing = ref(''), busy = ref(false)
const checked=ref<Server[]>([]),removing=ref(false),removalBusy=ref(false),removalIDs=ref<string[]>([]),removalPreview=ref<{token:string;nodes:{node:string;websites:{name:string;url:string}[]}[]}>(),revision=ref('')
async function removePreview(rows:Server[]){error.value='';if(!rows.length||rows.length>20||rows.some(r=>r.central)){error.value='请选择当前列表的 1～20 台子服务器；主服务器禁止移除';return};removing.value=true;removalPreview.value=undefined;removalBusy.value=true;try{const settings=await api<Settings>('/api/settings');revision.value=settings.revision;removalIDs.value=rows.map(r=>r.id);removalPreview.value=await api('/api/servers/remove/preview','POST',{ids:removalIDs.value,revision:revision.value})}catch(e){error.value=errorMessage(e)}finally{removalBusy.value=false}}
async function removeNodes(){if(!removalPreview.value)return;removalBusy.value=true;try{const job=await api<{id:string}>('/api/servers/remove','POST',{ids:removalIDs.value,revision:revision.value,token:removalPreview.value.token,confirm:true,request_key:requestKey()});removing.value=false;await router.push(`/deployments/${job.id}`)}catch(e){error.value=errorMessage(e)}finally{removalBusy.value=false}}
const selected = computed(() => items.value.find(n => n.id === String(route.params.id || '')))
const filtered = computed(() => items.value.filter(n => `${n.name} ${n.host} ${n.id}`.toLowerCase().includes(q.value.toLowerCase()) && (!status.value || n.status === status.value)))
const specs = computed(() => tab.value === 'health' ? healthCharts : resourceCharts)
const devices = computed(() => dimensions('disk_read:'))
const networks = computed(() => dimensions('net_receive:'))
function dimensions(prefix: string) { return Object.keys(selected.value?.snapshot.values || {}).filter(k => k.startsWith(prefix)).map(k => k.slice(prefix.length)).sort() }
function queryRange() { if (hours.value !== 0) return rangeQuery(hours.value); const start = Date.parse(customStart.value + '+08:00'), end = Date.parse(customEnd.value + '+08:00'); if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start || end-start > 90*86400000) throw new Error('请选择有效的起止时间，范围不能超过 90 天'); return new URLSearchParams({ start: String(Math.floor(Date.parse(customStart.value + '+08:00') / 1000)), end: String(Math.floor(Date.parse(customEnd.value + '+08:00') / 1000)) }) }
let inputTimer:ReturnType<typeof setTimeout>|undefined, previousID='', generation = 0, disposed = false, timer: ReturnType<typeof setInterval> | undefined
async function load() {if(disposed||document.hidden||busy.value)return;busy.value=true;const current=generation;try{const list=await servers();if(current!==generation||disposed)return;items.value=list.items;const id=selected.value?.id;if(id&&tab.value==='system'){try{const state=await api<typeof systemHealth.value>('/api/system/health');if(current===generation&&!disposed){systemHealth.value=state;systemError.value=''}}catch(e){if(current===generation&&!disposed)systemError.value=errorMessage(e)}}else if(id){const trend=await api<Trend>(`/api/servers/${encodeURIComponent(id)}/metrics?${queryRange()}`);if(current===generation&&!disposed)data.value=trend}if(current===generation&&!disposed)error.value=''}catch(e){if(current===generation&&!disposed)error.value=errorMessage(e)}finally{busy.value=false;if(!disposed&&current!==generation)void load()}}
function detail(id:string){return {path:`/servers/${encodeURIComponent(id)}`,query:{return_q:q.value||undefined,return_status:status.value||undefined}}}
function back(){void router.push({path:'/servers',query:Object.fromEntries(queryParams({q:route.query.return_q,status:route.query.return_status}))})}
function delayedList(){clearTimeout(inputTimer);inputTimer=setTimeout(saveList,300)}
function saveList(){clearTimeout(inputTimer);void router.replace({path:'/servers',query:Object.fromEntries(queryParams({q:q.value,status:status.value}))})}
function change(id:string){void router.push({path:`/servers/${encodeURIComponent(id)}`,query:{...route.query,tab:tab.value==='system'&&id!=='central'?'health':tab.value,device:undefined,network:undefined}})}
function setTab(value:string){void router.replace({path:route.path,query:{...route.query,tab:value}})}
function saveRange(){if(hours.value===0&&!customStart.value){const local=(date:Date)=>new Date(date.getTime()+8*3600000).toISOString().slice(0,16);customEnd.value=local(new Date());customStart.value=local(new Date(Date.now()-3600000))};void router.replace({path:route.path,query:{...route.query,...Object.fromEntries(queryParams({hours:hours.value,start:hours.value===0?customStart.value:undefined,end:hours.value===0?customEnd.value:undefined})),start:hours.value===0?customStart.value:undefined,end:hours.value===0?customEnd.value:undefined}})}
function saveDevices(){void router.replace({path:route.path,query:{...route.query,device:device.value||undefined,network:networkDevice.value||undefined}})}
function parseRoute(){hours.value=[0,1,6,24,168].includes(Number(route.query.hours))?Number(route.query.hours):1;customStart.value=String(route.query.start||'');customEnd.value=String(route.query.end||'');device.value=String(route.query.device||'');networkDevice.value=String(route.query.network||'');tab.value=['resources','health','system'].includes(String(route.query.tab))?String(route.query.tab):'resources';if(route.params.id!=='central'&&tab.value==='system')tab.value='health';if(!route.params.id){q.value=String(route.query.q||'');status.value=String(route.query.status||'')}}
function edit(id = '') { editing.value = id; nodeDialog.value = true }
function refresh() { if (!document.hidden) void load() }
watch(()=>route.fullPath,()=>{parseRoute();generation++;if(previousID!==String(route.params.id||'')){data.value.points=[];previousID=String(route.params.id||'')}void load()})
onMounted(() => { parseRoute();void load(); timer = setInterval(refresh, 30000); document.addEventListener('visibilitychange', refresh) })
onUnmounted(() => { disposed = true; generation++; clearTimeout(inputTimer);clearInterval(timer); document.removeEventListener('visibilitychange', refresh) })
</script>
<template>
 <el-alert v-if="error" :title="error" type="error" :closable="false" />
 <el-button v-if="route.params.id" class="back-button" @click="back">← 返回服务器列表</el-button>
 <el-alert v-if="route.params.id && !selected && !busy" title="服务器不存在或已移除，请返回服务器列表。" type="warning" :closable="false"/>
 <template v-if="!route.params.id">
 <el-card shadow="never"><div class="filters"><el-input v-model="q" placeholder="搜索名称、IP、节点 ID" clearable @input="delayedList" @clear="saveList" @keyup.enter="saveList" /><el-select v-model="status" placeholder="全部状态" clearable :value-on-clear="''" @change="saveList"><el-option v-for="s in ['normal','unreachable','stale','unknown','disabled']" :key="s" :label="statusLabel(s)" :value="s" /></el-select><el-button type="primary" @click="edit()">添加子服务器</el-button><el-button @click="load">刷新</el-button></div>
 <el-button type="danger" :disabled="!checked.length" @click="removePreview(checked)">卸载并移除已选（{{checked.length}}）</el-button><el-table :data="filtered" @selection-change="checked=$event" empty-text="尚未登记服务器或采集尚未就绪"><el-table-column type="selection" :selectable="(row:Server)=>!row.central&&row.can_remove!==false" width="48"/><el-table-column label="服务器" min-width="180"><template #default="{ row }"><router-link :to="detail(row.id)">{{ row.name }}</router-link><small class="muted" style="display:block">{{ row.host }} · {{ row.central ? '主服务器' : row.id }}</small></template></el-table-column><el-table-column label="状态" min-width="120"><template #default="{ row }"><el-tag :type="row.status === 'normal' ? 'success' : row.status === 'unreachable' ? 'danger' : 'info'">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column v-for="[key,label] in [['cpu_percent','CPU'],['memory_percent','内存'],['disk_percent','最满磁盘']]" :key="key" :label="label" min-width="110"><template #default="{ row }">{{ row.status === 'normal' ? metricValue(row.snapshot.values[key!], '%') : '未知' }}</template></el-table-column><el-table-column label="部署方式 / 版本" min-width="210"><template #default="{row}">{{runtimeLabel(row.actual_mode)}} · {{row.agent_version || (row.central ? '中心服务' : '旧版 / 未知')}}<small v-if="row.pending_mode" class="muted">待应用：{{runtimeLabel(row.configured_mode)}}</small><small v-if="!row.central" class="muted">{{deploymentLabel(row.deployment_state)}}</small></template></el-table-column><el-table-column label="最近采集" min-width="190"><template #default="{ row }">{{ beijingTime(row.snapshot.time) }}</template></el-table-column><el-table-column label="操作" min-width="260"><template #default="{ row }"><el-button link type="primary" @click="router.push(detail(row.id))">详情</el-button><el-button v-if="!row.central" link type="primary" @click="edit(row.id)">编辑配置</el-button><el-button v-if="!row.central" link type="danger" :disabled="row.can_remove===false" :title="row.remove_reason" @click="removePreview([row])">卸载并移除</el-button></template></el-table-column></el-table></el-card>
 </template>
 <template v-else-if="selected">
 <el-card shadow="never"><div class="filters"><el-select :model-value="selected?.id" @change="change"><el-option v-for="node in items" :key="node.id" :label="`${node.name} · ${node.host} · ${statusLabel(node.status)}`" :value="node.id" /></el-select><el-select v-model="hours" @change="saveRange"><el-option v-for="[value,label] in [[1,'最近 1 小时'],[6,'最近 6 小时'],[24,'最近 24 小时'],[168,'最近 7 天']]" :key="value" :value="value" :label="String(label)" /><el-option :value="0" label="自定义时间范围" /></el-select><span v-if="hours === 0" class="filters"><label>起始（北京时间）<input v-model="customStart" type="datetime-local" @change="saveRange" /></label><label>结束（北京时间）<input v-model="customEnd" type="datetime-local" @change="saveRange" /></label></span><el-select v-if="tab==='resources'" v-model="device" @change="saveDevices" clearable :value-on-clear="''" placeholder="全部磁盘汇总"><el-option v-for="d in devices" :key="d" :value="d" :label="d" /></el-select><el-select v-if="tab==='resources'" v-model="networkDevice" @change="saveDevices" clearable :value-on-clear="''" placeholder="物理网卡汇总"><el-option v-for="d in networks" :key="d" :value="d" :label="d" /></el-select><el-button @click="load">刷新</el-button></div><p class="muted">最近采集：{{ beijingTime(selected?.snapshot.time || 0) }} · {{ statusLabel(selected?.status || 'unknown') }} · 曲线精度 {{ data.resolution_seconds }} 秒；缺失数据留空。</p><el-alert v-if="selected && selected.status !== 'normal'" :title="selected.snapshot.error || '当前没有新鲜数据，历史曲线仍可查看'" type="warning" :closable="false" /><el-alert v-if="selected.snapshot.info?.collector_errors" :title="`部分指标采集失败：${selected.snapshot.info.collector_errors}；其他指标继续展示`" type="warning" :closable="false"/><el-alert v-if="tab === 'health' && selected.snapshot.info?.transport_error" :title="`最近投递失败：${selected.snapshot.info.transport_error}`" type="warning" :closable="false" /><p class="muted">实际部署：{{runtimeLabel(selected.actual_mode)}} · 配置方式：{{runtimeLabel(selected.configured_mode)}} · 版本：{{selected.agent_version || '未知'}}<span v-if="selected.pending_mode"> · 部署方式修改尚未应用</span></p><p v-if="selected?.snapshot.info" class="muted">主机：{{ selected.snapshot.info.nodename || '未知' }} · 系统：{{ selected.snapshot.info.sysname }} {{ selected.snapshot.info.release }} · 架构：{{ selected.snapshot.info.machine }}</p><div class="detail-grid" v-if="selected"><div v-for="[key,label,unit] in [['cpu_cores','CPU 核数',''],['uptime','运行时间','s'],['memory_total','总内存','B'],['webscan_watches','监听目录数','']]" :key="key"><span>{{ label }}</span><strong>{{selected.central && key==='webscan_watches'?'不适用':metricValue(selected.snapshot.values[key!], unit)}}</strong></div></div><div class="filters" ><el-button :type="tab === 'resources' ? 'primary' : ''" @click="setTab('resources')">资源指标</el-button><el-button :type="tab === 'health' ? 'primary' : ''" @click="setTab('health')">事件投递</el-button><el-button v-if="selected.central" :type="tab==='system'?'primary':''" @click="setTab('system')">中心健康</el-button><router-link :to="`/alerts?node=${selected?.id}`">相关告警 →</router-link></div></el-card>
 <el-alert v-if="tab==='system' && systemError" :title="systemError" type="error" :closable="false"/> <el-card v-if="tab==='system' && selected?.central && systemHealth" shadow="never"><h3>监控中心健康</h3><div class="detail-grid"><div><span>数据模式</span><strong>{{ systemHealth.mode === 'native' ? 'Go 一体化' : '旧组件兼容' }}</strong></div><div><span>事件数据库访问</span><strong>{{systemHealth.database==='normal'?'正常':statusLabel(systemHealth.database)}}</strong></div><div><span>待发送飞书消息</span><strong>{{ systemHealth.pending_notifications }}</strong></div><div><span>宿主机管理服务</span><strong>{{ systemHealth.manager.available ? '可用' : '不可用' }}</strong></div><div><span>待发送邮箱消息</span><strong>{{systemHealth.pending_email}}</strong></div></div><p class="muted">最早待投递时间：{{systemHealth.oldest_pending?beijingTime(systemHealth.oldest_pending):'无待投递消息'}} · 邮箱最早待投递：{{systemHealth.oldest_email?beijingTime(systemHealth.oldest_email):'无待投递消息'}}；看门狗：{{ systemHealth.manager.watchdog_phase === 'firing' ? '曾发现主服务异常，等待恢复确认' : systemHealth.manager.available ? '运行中' : systemHealth.manager.message }}。部署期间抑制看门狗故障通知。</p></el-card>
<div v-if="tab!=='system'" class="chart-grid"><MetricChart v-for="spec in specs" :key="spec.title" :title="spec.title" :option="trendOption(data.points, spec, spec.keys.some(k => k.startsWith('net_')) ? networkDevice : spec.keys.some(k => k.startsWith('disk_read')) ? device : '', selected?.status === 'normal' ? selected.snapshot.values : {})" /></div>
 <el-card shadow="never" v-if="selected && tab === 'health'"><h3>事件投递与监控链路指标</h3><el-table :empty-text="selected.central?'不适用：主服务器不运行节点 Agent':'尚未取得链路指标'" :data="Object.entries(selected.snapshot.values).filter(([key]) => key.startsWith('webscan_')).map(([key,value]) => ({ key: metricLabel(key),value }))"><el-table-column prop="key" label="指标" min-width="220" /><el-table-column prop="value" label="最近数值" /></el-table><p class="muted">{{selected.central?'主服务器不运行节点 Agent，对应指标不适用。':'缺失指标表示尚未取得数据。'}}纯指标端点失联不等于服务器关机。</p></el-card>
 </template>
 <el-dialog v-model="removing" title="卸载监控并移除子服务器" width="min(700px,96vw)" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false"/><p>仅处理明确选择的 {{removalIDs.length}} 台服务器。逐台卸载并验收后移除配置；失败时暂停后续节点，保留失败节点配置，已完成节点不会重复卸载。</p><p>远端数据、业务目录、Docker 引擎及其他容器保留；关联网站转由主服务器检测，原故障与通知历史保留。</p><div v-for="node in removalPreview?.nodes" :key="node.node"><strong>{{node.node}}</strong><p>关联网站：{{node.websites.map(w=>w.name+' '+w.url).join('、')||'无'}}</p></div><template #footer><el-button :disabled="removalBusy" @click="removing=false">取消</el-button><el-button type="danger" :loading="removalBusy" :disabled="!removalPreview" @click="removeNodes">确认卸载并移除</el-button></template></el-dialog><NodeDialog v-model="nodeDialog" :node-id="editing" @saved="load" />
</template>

<style scoped>.back-button{margin-bottom:16px;max-width:100%}</style>
